module typo_checker (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] word_count,\n    input wire [511:0] words,\n    input wire [31:0] word_lengths,\n    output reg pair_valid,\n    output reg [3:0] word1_idx,\n    output reg [3:0] word2_idx,\n    output reg done\n);\n\n    // State definitions\n    localparam [3:0] S_IDLE = 4'd0;\n    localparam [3:0] S_LOAD = 4'd1;\n    localparam [3:0] S_LOOP_I = 4'd2;\n    localparam [3:0] S_LOOP_J = 4'd3;\n    localparam [3:0] S_CHECK = 4'd4;\n    localparam [3:0] S_OUTPUT = 4'd5;\n    localparam [3:0] S_INCREMENT_J = 4'd6;\n    localparam [3:0] S_INCREMENT_I = 4'd7;\n    localparam [3:0] S_DONE = 4'd8;\n\n    // Internal registers\n    reg [3:0] state;\n    reg [2:0] i, j;\n    reg [2:0] i_reg, j_reg;\n    reg [63:0] words_reg [0:7];\n    reg [3:0] word_lengths_reg [0:7];\n\n    // Similarity check output\n    wire is_similar;\n\n    // Instantiate similarity module\n    similar sim_inst (\n        .word1(words_reg[i]),\n        .len1(word_lengths_reg[i]),\n        .word2(words_reg[j]),\n        .len2(word_lengths_reg[j]),\n        .is_similar(is_similar)\n    );\n\n    // State machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= S_IDLE;\n            pair_valid <= 1'b0;\n            done <= 1'b0;\n            i <= 3'd0;\n            j <= 3'd0;\n            i_reg <= 3'd0;\n            j_reg <= 3'd0;\n            integer w;\n            for (w = 0; w < 8; w = w + 1) begin\n                words_reg[w] <= 64'd0;\n                word_lengths_reg[w] <= 4'd0;\n            end\n        end else begin\n            case (state)\n                S_IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= S_LOAD;\n                    end\n                end\n\n                S_LOAD: begin\n                    integer w;\n                    for (w = 0; w < 8; w = w + 1) begin\n                        words_reg[w] <= words[w*64 +: 64];\n                        word_lengths_reg[w] <= word_lengths[w*4 +: 4];\n                    end\n                    i <= 3'd0;\n                    j <= 3'd0;\n                    state <= S_LOOP_I;\n                end\n\n                S_LOOP_I: begin\n                    if (word_count <= 4'd1) begin\n                        state <= S_DONE;\n                    end else if (i < word_count - 1) begin\n                        j <= i + 1;\n                        state <= S_LOOP_J;\n                    end else begin\n                        state <= S_DONE;\n                    end\n                end\n\n                S_LOOP_J: begin\n                    if (j < word_count) begin\n                        state <= S_CHECK;\n                    end else begin\n                        state <= S_INCREMENT_I;\n                    end\n                end\n\n                S_CHECK: begin\n                    if (is_similar) begin\n                        i_reg <= i;\n                        j_reg <= j;\n                        state <= S_OUTPUT;\n                    end else begin\n                        state <= S_INCREMENT_J;\n                    end\n                end\n\n                S_OUTPUT: begin\n                    pair_valid <= 1'b1;\n                    word1_idx <= i_reg;\n                    word2_idx <= j_reg;\n                    state <= S_INCREMENT_J;\n                end\n\n                S_INCREMENT_J: begin\n                    pair_valid <= 1'b0;\n                    j <= j + 1;\n                    state <= S_LOOP_J;\n                end\n\n                S_INCREMENT_I: begin\n                    i <= i + 1;\n                    state <= S_LOOP_I;\n                end\n\n                S_DONE: begin\n                    done <= 1'b1;\n                    state <= S_IDLE;\n                end\n\n                default: state <= S_IDLE;\n            endcase\n        end\n    end\n\nendmodule\n\nmodule similar (\n    input [63:0] word1,\n    input [3:0] len1,\n    input [63:0] word2,\n    input [3:0] len2,\n    output reg is_similar\n);\n\n    always @(*) begin\n        is_similar = 1'b0;\n\n        // Check delete: len1 = len2 + 1\n        if (len1 == len2 + 1) begin\n            integer k;\n            for (k = 0; k < 8; k = k + 1) begin\n                if (k < len1) begin\n                    integer m;\n                    bit match;\n                    match = 1'b1;\n                    // Check prefix\n                    for (m = 0; m < k; m = m + 1) begin\n                        if (word1[8*m +:8] != word2[8*m +:8]) match = 1'b0;\n                    end\n                    // Check suffix\n                    for (m = k; m < len2; m = m + 1) begin\n                        if (word1[8*(m+1) +:8] != word2[8*m +:8]) match = 1'b0;\n                    end\n                    if (match) is_similar = 1'b1;\n                end\n            end\n        end\n\n        // Check insert: len2 = len1 + 1\n        else if (len2 == len1 + 1) begin\n            integer k;\n            for (k = 0; k < 8; k = k + 1) begin\n                if (k < len2) begin\n                    integer m;\n                    bit match;\n                    match = 1'b1;\n                    // Check prefix\n                    for (m = 0; m < k; m = m + 1) begin\n                        if (word2[8*m +:8] != word1[8*m +:8]) match = 1'b0;\n                    end\n                    // Check suffix\n                    for (m = k; m < len1; m = m + 1) begin\n                        if (word2[8*(m+1) +:8] != word1[8*m +:8]) match = 1'b0;\n                    end\n                    if (match) is_similar = 1'b1;\n                end\n            end\n        end\n\n        // Check replace and transpose: len1 == len2\n        else if (len1 == len2) begin\n            // Check replace: exactly one character difference\n            integer diff_count;\n            diff_count = 0;\n            for (integer k = 0; k < 8; k = k + 1) begin\n                if (k < len1) begin\n                    if (word1[8*k +:8] != word2[8*k +:8]) diff_count = diff_count + 1;\n                end\n            end\n            if (diff_count == 1) is_similar = 1'b1;\n\n            // Check transpose: one adjacent swap\n            for (integer i = 0; i < 8; i = i + 1) begin\n                if (i < len1 - 1) begin\n                    bit match;\n                    match = 1'b1;\n                    // Check swapped pair\n                    if (word1[8*i +:8] != word2[8*(i+1) +:8]) match = 1'b0;\n                    if (word1[8*(i+1) +:8] != word2[8*i +:8]) match = 1'b0;\n                    // Check rest\n                    for (integer k = 0; k < len1; k = k + 1) begin\n                        if (k != i && k != i+1) begin\n                            if (word1[8*k +:8] != word2[8*k +:8]) match = 1'b0;\n                        end\n                    end\n                    if (match) is_similar = 1'b1;\n                end\n            end\n        end\n    end\n\nendmodule